-- Edible DC import. Generated by tools/import-edibledc-events.mjs.
-- Safe to re-run: upserts by source + external_id.

insert into public.venues (
  name, address, venue_type, neighborhood, source_name, source_key, website_url, image_url, raw_data, imported_at, created_at, updated_at
)
select
  venue_name,
  venue_address,
  venue_type,
  neighborhood,
  'Edible DC',
  'edibledc:venue:' || lower(regexp_replace(concat_ws('|', venue_name, venue_address), '[^a-z0-9]+', '-', 'g')),
  min_source_url,
  nullif(venue_image_url, ''),
  jsonb_build_object('edibledc_import', true, 'source_url', min_source_url),
  now(), now(), now()
from (
  select
    item->>'venue_name' as venue_name,
    item->>'venue_address' as venue_address,
    max(item->>'venue_type') as venue_type,
    max(item->>'neighborhood') as neighborhood,
    min(item->>'external_url') as min_source_url,
    max(item->>'image_url') as venue_image_url
  from jsonb_array_elements('[{"title":"Spill Fest","description":"The Legendary Afro-Caribbean Music & Food Festival\nGet ready for one of the hottest outdoor celebrations of the summer!\nJoin us for an unforgettable evening of music, culture, food, and community as we transform Metrobar into the ultimate Afro-Caribbean festival experience.\n📅 Saturday, August 1, 2026\n🕔 5:00 PM – 11:00 PM\n📍 Metrobar | Washington, DC\n\n🎧 Featuring\n\nDJ Majestic\nClaude Di Martian\nPrince Royal\nTerri The Hippiie\nCurry\n\n🍴 Festival Experience\n\nOutdoor dance party\nAfro-Caribbean food vendors\nFull-service bars\n\n🥂 Bottle Service & VIP\nFor bottle service or VIP reservations, text:\n(202) 422-9030\n🌙 Official After Party\nLucky Bar\n🕚 11:00 PM – 3:00 AM\nOne ticket. Two experiences. Keep the party going after Spill Fest ends.\nPresented by Grandiose Group & Event Fanatics\n\nFAQ:\n\nSpill Fest will be held RAIN OR SHINE!\nAge requirement? 21+\nDoes the ticket price include food? Ticket price includes Main stage entertainment. Food and Beverage are additional features.\nAre tickets refundable? Tickets are non-refundable.\nDoes the event provide parking? No, but there is ample free parking in the lot next to Metrobar\nCan I bring in my own food and drinks? No food or liquids will be allowed into the venue.\nWill alcohol be served? Yes, alcohol will be served.\nWill Food be Provided? Yes, we will have Afro-Caribbean Food Vendors.\nWhat time should I get there? The earlier the better, gates will open at 5:00 PM\nIs there any seating provided? Limited seating available, 1st come 1st serve. Seating provided with VIP bottle service.\nCan I bring lawn chairs or coolers? NO, Lawn chairs, igloos, coolers, umbrellas, and blankets are not allowed. Tents are prohibited.\nCan I bring an umbrella? For the safety of all guests, umbrellas will not be admitted.\nAre the event grounds grass? NO, the venue grounds are concrete","category":"nightlife","tag":"Food festival","tags":["Food festival","Community","International","DJ Set"],"venue_name":"metrobar","venue_address":"640 Rhode Island Avenue Northeast, Washington, DC, 20002","venue_type":"Event Venue","neighborhood":"NoMa / Union Market Area","date":"2026-08-01","time":"5:00 PM","starts_at":"2026-08-01T17:00:00-04:00","ends_at":"2026-08-01T23:00:00-04:00","timezone":"America/New_York","price":"","price_min":"","price_max":"","is_free":false,"source":"edibledc","external_id":"7716-1785603600-1785625200@edibledc.com","ticket_url":"","external_url":"https://edibledc.com/event/spill-fest/","image_url":"https://edibledc.com/wp-content/uploads/2026/07/741727293_1064775386221792_8184900711300551604_n.jpg","raw_json":{"uid":"7716-1785603600-1785625200@edibledc.com","location":"metrobar, 640 Rhode Island Avenue Northeast, Washington, DC, 20002","source_url":"https://edibledc.com/event/spill-fest/","imported_from":"https://edibledc.com/events/?ical=1"},"status":"published"},{"title":"Foraging Walk with Robin Greenfield in Washington, D.C.","description":"For one year Robin Greenfield is foraging every bite of his food and medicine. A year without grocery stores, restaurants, pharmacies or even a garden. “Nature” is his garden!\nThis is a practice of love and devotion for Earth. Throughout this year, he is traveling across the nation educating on the food and medicine that is growing freely and abundantly all around us. He is here to support us on our journey of living more closely connected with Earth and to build up the foraging community.\nJoin us for a Foraging Walk in New York to learn how to safely and sustainably forage the common edible and medicinal plants that most of us pass by without even knowing!\nRobin will introduce you to:\n– 10+ common edible and medicinal plants growing in your area\n– How to safely forage\n– How to harvest sustainably and be a friend to the plants\n– Simple strategies for successful foraging\nThis event is accessible to all, regardless of experience. We generally walk less than a half mile total, and no more than 10 minutes from the starting point.\nOur hope is for you to leave this Foraging Walk informed, inspired, motivated and with a sense of community to make foraging a foundational part of your life!\nEvent Details:\nUnited States Capitol\nFirst St SE, Washington, DC 20004\nMeet at the Lawn on the South East Corner on 1st St and Southeast Dr\nAugust 4th at 6-8 PM\nSuggested donation $10-40 to support our grassroots service to Earth, humanity and our plant and animal relatives through our nonprofit Regeneration, Equity and Justice.\n\nWe strive for our events to be accessible to all, regardless of financial means. To apply for a scholarship to attend, simply fill out this form.","category":"food","tag":"Local food","tags":["Local food","Community","Outdoor"],"venue_name":"United States Capitol","venue_address":"First St SE, Washington, DC, 20004","venue_type":"Food / Culinary Venue","neighborhood":"Capitol Hill","date":"2026-08-04","time":"6:00 PM","starts_at":"2026-08-04T18:00:00-04:00","ends_at":"2026-08-04T20:00:00-04:00","timezone":"America/New_York","price":"$10","price_min":10,"price_max":10,"is_free":false,"source":"edibledc","external_id":"7745-1785866400-1785873600@edibledc.com","ticket_url":"","external_url":"https://edibledc.com/event/foraging-walk-with-robin-greenfield-in-washington-d-c/","image_url":"https://edibledc.com/wp-content/uploads/2026/07/lliekvy0ne43cu4jujk1.jpg","raw_json":{"uid":"7745-1785866400-1785873600@edibledc.com","location":"United States Capitol, First St SE, Washington, DC, 20004","source_url":"https://edibledc.com/event/foraging-walk-with-robin-greenfield-in-washington-d-c/","imported_from":"https://edibledc.com/events/?ical=1"},"status":"published"},{"title":"Carefree Black Girl Cookout","description":"CareFreeBlackGirl Cookout\n A Celebration of Black Femme Joy\nGet ready for an immersive day festival experience where culture, community, and carefree vibes collide. This month, we’re bringing the heat with our signature Cookout a celebration of Black femmes in all their power, style, and brilliance.\n\nLocation:  Sycamore and Oak \n1110 OAK DR. SE \nWASHINGTON DC 20032\nTime: 2pm – 8pm \nWhat to Expect\nAll-Black Women Lineup: DJs, performers, and hosts that bring the energy\nLocal Vendors: Shop Black, femme, and community-owned\nCreative Activations\nGiveaways + Good Vibes: Because we don’t do boring\nGames, Food, and Freedom: Expect a full experience curated with love\nFree Food for the First Hour: Come early!\nFood & Drinks will also be available for purchase all day from Sycamor & Oaks Current FOOD VENDORS\n Activitions included with your ticket :\nWellness Activities w/ Not A Bad Life\nSound Baths w/ One Holistic\n& MORE\nWhat to Bring\nYour full self\nComfy fits\nAn open heart and a whole lot of joy\nRSVP now and get ready to turn up with the tribe.\nMUSIC. CULTURE. MELANIN MAGIC.\nAll are welcome all ages, races, and genders.\nPlease note: this is an adult-focused experience. Children under 13 are free but must be accompanied by an adult at all times.\nPlease Note\nNo refunds unless event is canceled or postponed\nInstagram @carefreeblackgirlinc_\nThis isn’t just a cookout, it’s a movement.\nThe CareFreeBlackGirl CookOut is a safe space for Black femmes and allies to celebrate in full color. Come for the vibes, leave with community.\nLOOKING TO VEND, SUBMIT HERE","category":"food","tag":"Food festival","tags":["Food festival","Market","Community","DJ Set"],"venue_name":"Sycamore and Oak","venue_address":"1110 OAK DR. SE, Washington, DC, 20032","venue_type":"Food / Culinary Venue","neighborhood":"Congress Heights","date":"2026-08-08","time":"2:00 PM","starts_at":"2026-08-08T14:00:00-04:00","ends_at":"2026-08-08T20:00:00-04:00","timezone":"America/New_York","price":"","price_min":"","price_max":"","is_free":false,"source":"edibledc","external_id":"7762-1786197600-1786219200@edibledc.com","ticket_url":"","external_url":"https://edibledc.com/event/carefree-black-girl-cookout/","image_url":"https://edibledc.com/wp-content/uploads/2026/07/image_1781009736734_s44opz4sg.jpeg","raw_json":{"uid":"7762-1786197600-1786219200@edibledc.com","location":"Sycamore and Oak, 1110 OAK DR. SE, Washington, DC, 20032","source_url":"https://edibledc.com/event/carefree-black-girl-cookout/","imported_from":"https://edibledc.com/events/?ical=1"},"status":"published"},{"title":"2026 Tomato Party at Common Good City Farm","description":"Celebrate all things tomato at our annual Tomato Party!\nSummer is the perfect season to enjoy fresh tomatoes. Come enjoy an evening at Common Good City Farm, taste different tomato varieties, try various tomato dishes and more!\n\nAt this FREE event you can:\n\nEat your heart and belly full of tomato-ey foods!\nTaste a variety of tomatoes\nEnjoy tomato-themed crafts and games\n\nThis event also serves as a back to school fundraiser to support our local youth with supplies and to support Common Good’s programming!\nHere are the ways to give to our community:\n\nMake a monetary donation with your ticket to support our food access and youth programs\nBring new school supplies to help our local youth start their school year fresh!\n\nSchool Supplies Most Needed: Backpacks, notebooks, folders, glue sticks, crayons, pencils, highlighters.\n\nMake a donation at the event bar and try a delicious summer mocktail or cocktail","category":"culture","tag":"Local food","tags":["Local food","Author talk","Community"],"venue_name":"Common Good City Farm","venue_address":"300 V St NW Washington, D.C. 20001","venue_type":"Event Venue","neighborhood":"Washington DC","date":"2026-08-13","time":"6:00 PM","starts_at":"2026-08-13T18:00:00-04:00","ends_at":"2026-08-13T20:00:00-04:00","timezone":"America/New_York","price":"","price_min":"","price_max":"","is_free":true,"source":"edibledc","external_id":"7795-1786644000-1786651200@edibledc.com","ticket_url":"","external_url":"https://edibledc.com/event/2026-tomato-party-at-common-good-city-farm/","image_url":"https://edibledc.com/wp-content/uploads/2026/07/97d654da-5df4-4e63-9186-76e36ad015d1.png@responsive-2400.webp","raw_json":{"uid":"7795-1786644000-1786651200@edibledc.com","location":"Common Good City Farm, 300 V St NW Washington, D.C. 20001","source_url":"https://edibledc.com/event/2026-tomato-party-at-common-good-city-farm/","imported_from":"https://edibledc.com/events/?ical=1"},"status":"published"},{"title":"Panda Fest Washington D.C.","description":"PANDA FEST is one of the biggest outdoor Asian food festivals in the US with experiential activities, tastings, and market fairs that showcases the vibrant food, art and cultural traditions from Asia.\n\n2026 TIME\n\nAUGUST 15-16, 2026\n\nLOCATION\n\n6th St NW & Pennsylvania Ave NW\nWashington, DC 20004\n\nHOURS\n\nSaturday: 10 am to 10pm\nSunday: 10 am to 8pm\n\nMerchandise\n\n90+ Asian food vendors\n200+ Asian street food\n40+ Merchandise vendors\n\nEarly Bird – $10 (Ends on 5/31/2026 10PM EDT, or when the 1000 tickets per time slot are sold out, whichever comes first)\nGeneral Admission – $14\nVIP – $35\nTickets are non-refundable\n\nWhat can I expect？\n2 FREE GIFTS: one customized Panda pin with DC feature, one headband (worth $11)\n90+ Asian food vendors\n200 + Asian street food\n40 + Merchandise vendors\nAsian culture performance\nPanda related merchandise\nPanda inflatable\nPanda bounce house","category":"food","tag":"Food festival","tags":["Food festival","Market","Community","Outdoor"],"venue_name":"6th St NW & Pennsylvania Ave NW","venue_address":"6th St NW & Pennsylvania Ave NW, Washington, DC, 20004","venue_type":"Food / Culinary Venue","neighborhood":"Washington DC","date":"2026-08-15","time":"10:00 AM","starts_at":"2026-08-15T10:00:00-04:00","ends_at":"2026-08-16T20:00:00-04:00","timezone":"America/New_York","price":"$10 - $35","price_min":10,"price_max":35,"is_free":false,"source":"edibledc","external_id":"7737-1786788000-1786910400@edibledc.com","ticket_url":"","external_url":"https://edibledc.com/event/panda-fest-washington-d-c/","image_url":"https://edibledc.com/wp-content/uploads/2026/07/5M7A5908.webp","raw_json":{"uid":"7737-1786788000-1786910400@edibledc.com","location":"6th St NW & Pennsylvania Ave NW, 6th St NW & Pennsylvania Ave NW, Washington, DC, 20004","source_url":"https://edibledc.com/event/panda-fest-washington-d-c/","imported_from":"https://edibledc.com/events/?ical=1"},"status":"published"},{"title":"Central Table -- Volume Three","description":"Join us Saturday, August 29th for the next event in my pop-up dinner series: CENTRAL TABLE. This month, the event will be hosted in partnership with local non-profit Slow Food DC, and the meal feature ingredients from several local producers who have won their Snail of Approval Award. Kevin Arwood will be sharing some of the foods he loves to cook and the stories that go along with them. And a few of the local producers will join us to share more about their operations and special ingredients.\nCENTRAL TABLE brings fellow foodies together who may have never crossed paths, yet share a desire for good food, good energy, and authentic human connection. Guest will enjoy a beautifully curated, locally sourced, multi-course meal served at a single central table where the atmosphere is warm and intentionally welcoming. Expect eclectic stories, light laughter, and the kind of organic connections that happen when people come together without pretense or pressure. CENTRAL TABLE is perfect for anyone who enjoys meeting new people, tasting new perspectives, and savoring a sense of community through food. Come with an open mind. Leave with a full heart, a happy palate, and maybe even a new friend.\nTickets are $150 plus processing fees.","category":"food","tag":"Chef dinner","tags":["Chef dinner","Community"],"venue_name":"Mess Hall","venue_address":"703 Edgewood St NE, DC, 20017, United States","venue_type":"Food / Culinary Venue","neighborhood":"NoMa / Union Market Area","date":"2026-08-29","time":"7:00 PM","starts_at":"2026-08-29T19:00:00-04:00","ends_at":"2026-08-29T22:00:00-04:00","timezone":"America/New_York","price":"$150","price_min":150,"price_max":150,"is_free":false,"source":"edibledc","external_id":"7769-1788030000-1788040800@edibledc.com","ticket_url":"","external_url":"https://edibledc.com/event/central-table-volume-three/","image_url":"https://edibledc.com/wp-content/uploads/2026/07/b37769209ccb5e8e737823e06535208c.jpeg","raw_json":{"uid":"7769-1788030000-1788040800@edibledc.com","location":"Mess Hall, 703 Edgewood St NE, DC, 20017, United States","source_url":"https://edibledc.com/event/central-table-volume-three/","imported_from":"https://edibledc.com/events/?ical=1"},"status":"published"},{"title":"Politics & Prose Presents: Chef Patrick O''Connell | Main, Middle & Gay","description":"For one night only, A Literary Coming Out Party starring Chef Patrick O’Connell with José Andrés and Tom Sietsema. Notice of Information Sharing: By purchasing a ticket to this event, you acknowledge that The George Washington University may share your contact information (name, email address, mailing address) with Politics and Prose for the purpose of advertising future events. You will have the opportunity to unsubscribe from these communications at any time. For general ticketing, event questions, or group ticket orders, please email gwticket@gwu.edu. Box office opens when doors open unless otherwise noted.","category":"culture","tag":"Author talk","tags":["Author talk"],"venue_name":"Lisner Auditorium","venue_address":"730 21st St NW, Washington, DC, 20037","venue_type":"Event Venue","neighborhood":"Foggy Bottom","date":"2026-09-18","time":"6:00 PM","starts_at":"2026-09-18T18:00:00-04:00","ends_at":"2026-09-18T22:00:00-04:00","timezone":"America/New_York","price":"","price_min":"","price_max":"","is_free":false,"source":"edibledc","external_id":"7776-1789754400-1789768800@edibledc.com","ticket_url":"","external_url":"https://edibledc.com/event/politics-prose-presents-chef-patrick-oconnell-main-middle-gay/","image_url":"https://edibledc.com/wp-content/uploads/2026/07/9781250436382f6b83.jpg","raw_json":{"uid":"7776-1789754400-1789768800@edibledc.com","location":"Lisner Auditorium, 730 21st St NW, Washington, DC, 20037","source_url":"https://edibledc.com/event/politics-prose-presents-chef-patrick-oconnell-main-middle-gay/","imported_from":"https://edibledc.com/events/?ical=1"},"status":"published"}]'::jsonb) item
  where nullif(item->>'venue_name', '') is not null
    and nullif(item->>'venue_address', '') is not null
  group by item->>'venue_name', item->>'venue_address'
) venue_item
on conflict (name, address) do update
set source_name = coalesce(public.venues.source_name, excluded.source_name),
    source_key = coalesce(public.venues.source_key, excluded.source_key),
    venue_type = coalesce(nullif(public.venues.venue_type, ''), excluded.venue_type),
    neighborhood = coalesce(nullif(public.venues.neighborhood, ''), excluded.neighborhood),
    website_url = coalesce(nullif(public.venues.website_url, ''), excluded.website_url),
    image_url = coalesce(nullif(public.venues.image_url, ''), excluded.image_url),
    raw_data = public.venues.raw_data || excluded.raw_data,
    updated_at = now();

insert into public.events (
  title, description, category, tag, tags, venue_name, venue, neighborhood, venue_address,
  date, time, starts_at, ends_at, timezone, price, price_min, price_max, is_free,
  source, external_id, ticket_url, external_url, url, image_url, raw_json, status,
  last_seen_at, created_at, updated_at
)
select
  item->>'title',
  item->>'description',
  item->>'category',
  item->>'tag',
  array(select jsonb_array_elements_text(item->'tags')),
  item->>'venue_name',
  item->>'venue_name',
  item->>'neighborhood',
  item->>'venue_address',
  nullif(item->>'date', '')::date,
  nullif(item->>'time', ''),
  nullif(item->>'starts_at', '')::timestamptz,
  nullif(item->>'ends_at', '')::timestamptz,
  item->>'timezone',
  nullif(item->>'price', ''),
  nullif(item->>'price_min', '')::numeric,
  nullif(item->>'price_max', '')::numeric,
  coalesce((item->>'is_free')::boolean, false),
  item->>'source',
  item->>'external_id',
  nullif(item->>'ticket_url', ''),
  item->>'external_url',
  item->>'external_url',
  nullif(item->>'image_url', ''),
  item->'raw_json',
  item->>'status',
  now(), now(), now()
